head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.MSG_NO_COMT = "위원회심사결과 내역이 없습니다. 새로 추가하시겠습니까?";
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strKeyLstBzProcsNo = "", scwin.strKeyIsurCd = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const arr = new Array();
        $c.elw.fn_searchCode();
        scwin.fn_GetPar = $c.frame.path("../").scwin.fn_GetPar;
        scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
        if (scwin.fn_GetPar !== undefined) {
            scwin.fn_GetPar(arr);
        }
        txb_IsurCd.setValue((arr.length >= 1 ? arr[0] : ""));
        scwin.strKeyIsurCd = (arr.length >= 1 ? arr[0] : "");
        scwin.strKeyLstBzProcsNo = (arr.length >= 2 ? arr[1] : "");
        txb_CoNm.setValue((arr.length >= 3 ? arr[2] : "")); // 발행기관명도 넘겨받아 컨트롤에 반영해야 한다.

        if (arr.length > 2) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05010_STK.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Cmt_OnLoadCompleted
 * @description dts_Cmt 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Cmt_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_Cmt.getRowCount() > 0) {
            scwin.setKeyCtrOnUpd(); // 조회직후에는 수정상태
            await scwin.searchReqInf();
        } else {
            if (confirm(scwin.MSG_NO_COMT)) {
                await scwin.addNewCmt();
            } else {
                await $c.win.closePopup(); // CloseFrame은 호출자가 있을경우 유효하다.

            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05010_STK.dts_Cmt_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Cmt_OnRowPosChanged
 * @description Cmt On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Cmt_OnRowPosChanged = async function(row) {
    try {
        if (dts_Cmt.getRowCount() > 0) {
            if (dts_Cmt.getCellData(row, "BZ_PROCS_NO") !== "") {
                await scwin.searchReqInf();
            }

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05010_STK.dts_Cmt_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name dts_ReqInf_OnLoadCompleted
 * @description dts_ReqInf 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReqInf_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name tr_Save_OnFail
 * @description tr Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Save_OnFail = async function() {
    try {
        await $c.win.alert(scwin.MSG_TR_FAIL);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05010_STK.tr_Save_OnFail" });
    }
};

/**
 * @method
 * @name tr_Save_OnSuccess
 * @description tr Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Save_OnSuccess = async function() {
    try {
        await $c.win.alert(scwin.MSG_TR_DOME);
        await scwin.search();

        // 상장위원회일, 심사구분 reLoad
        const parentWin = $c.frame.path("../");
        parentWin.fn_read_sync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05010_STK.tr_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name img_SetComiteDd_onclick
 * @description img_SetComiteDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SetComiteDd_onclick = function() {
    try {
        scwin.showCalendar(med_ComiteDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05010_STK.img_SetComiteDd_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05010_STK.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Save_onclick = async function() {
    try {
        await scwin.save("I");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05010_STK.img_Save_onclick" });
    }
};

/**
 * @method
 * @name img_Regist_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Regist_onclick = async function() {
    try {
        await scwin.addNewCmt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05010_STK.img_Regist_onclick" });
    }
};

/**
 * @method
 * @name img_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Delete_onclick = async function() {
    try {
        await scwin.deleteRow();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05010_STK.img_Delete_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    const arrCid = [{
        cid: "COMITE_INVSTG_RSLT_CD",
        cnm: "cmb_ComiteInvstgRsltCd"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT").replace(/,/g, "','");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name searchReqInf
 * @description search Req Inf 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchReqInf = async function() {
    const sbmOptions = {
        id : "sbm_dts_ReqInf",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ReqInf=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description 발행기관코드가 키값이다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 발행기관코드가 키값이다.

    const sbmOptions = {
        id : "sbm_dts_Cmt",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Cmt=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description save 처리
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function(jobType) {
    if (js_dep_cd.substring(0, 2) !== '25' && // 유가 - 상장부
        js_dep_cd !== '2615') {
        // 기업심사팀(2615) by nhkw
        await $c.win.alert("해당 부서만 접수가 가능합니다.");
        return;
    }

    // if(jobType == "D"){}  -- 삭제일 경우, 쿼리문도 수정해줘야 함.
    // else{

    // 위원회일/철회일 필수 체크
    // 1줄만 있을 경우, 삭제할 수 없음
    if (med_ComiteDd.getValue() === "") {
        await $c.win.alert("위원회일/철회일을 입력하여 주세요");
        med_ComiteDd.focus();
        return false;
    }
    // }

    let vScrenProcTpCd;
    if (jobType === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType === "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType === "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    if ($c.cp.isModified(dts_Cmt) || $c.cp.isModified(dts_ReqInf)) {
        dts_ReqInf.setCellData(1, "LST_COMITE_RSLT_SAVE_EMP_NO", scwin.getUserId());
        tr_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_tr_Save",
            action : "/Prelisting.do",
            ref : "dts_ReqInf,dts_Cmt",
            target : "tr_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } else {
        await $c.win.alert(scwin.MGS_NO_UPDT);
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getUserId
 * @description get User Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getUserId = function() {
    return js_emp_no;
};

/**
 * @method
 * @name showCalendar
 * @description show Calendar 처리
 * @param {*} o o
 * @returns {void}
 * @hidden N
 */
scwin.showCalendar = function(o) {
    if ((o !== undefined) && (!o.readOnly)) {
        popUpCalendar2(o);
    }
};

/**
 * @method
 * @name addNewCmt
 * @description add New Cmt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addNewCmt = async function() {
    dts_Cmt.insertRow();
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO", scwin.strKeyLstBzProcsNo);
    await scwin.searchReqInf();
    scwin.setKeyCtrOnAdd(); // 추가상태에서는  key컬럼수정가능

};

/**
 * @method
 * @name deleteRow
 * @description delete Row 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRow = async function() {
    dts_Cmt.removeRow(dts_Cmt.getRowPosition());
    await scwin.save("D");
};

/**
 * @method
 * @name setKeyCtrOnAdd
 * @description set Key Ctr On Add 처리
 * @returns {void}
 * @hidden N
 */
scwin.setKeyCtrOnAdd = function() {
    $c.lc.fn_setCtrWritable([med_ComiteDd]);
};

/**
 * @method
 * @name setKeyCtrOnUpd
 * @description set Key Ctr On Upd 처리
 * @returns {void}
 * @hidden N
 */
scwin.setKeyCtrOnUpd = function() {
    $c.lc.fn_setCtrReadOnly([med_ComiteDd]);
};
